resources.afterResponseScript:
// Guarda o token no ambiente ATIVO (o perfil escolhido no seletor de ambientes).
if (insomnia.response.code === 200) {
  insomnia.environment.set('token', insomnia.response.json().token);
}

// Preenche os ids de apoio (unidade, paciente, profissional, horário, leito...) para as URLs {{ _.xxx_id }}.
// Rode UMA vez, no ambiente Administrador, DEPOIS do Login.
const base = insomnia.variables.get('base_url');
const token = insomnia.environment.get('token');
const get = (p) => new Promise((ok, no) => insomnia.sendRequest(
  { url: base + p, method: 'GET', header: { Accept: 'application/json', Authorization: 'Bearer ' + token } },
  (e, r) => (e ? no(e) : ok(r.json()))));
const set = (k, v) => { if (v) insomnia.baseEnvironment.set(k, v); };
const passos = [
  async () => { const j = await get('/api/v1/auth/unidades'); set('unidade_id', (j.data.find(u => u.nome === 'VidaPlus Hospital Central') || j.data[0] || {}).id); },
  async () => { const j = await get('/api/v1/pacientes?nome=' + encodeURIComponent('Ana Maria')); set('paciente_id', (j.data[0] || {}).id); },
  async () => { const j = await get('/api/v1/profissionais'); set('profissional_id', (j.data.find(p => p.especialidade === 'Clínica Geral') || j.data[0] || {}).id); },
  async () => { const j = await get('/api/v1/leitos'); set('leito_id', (j.data[0] || {}).id); },
  async () => { const j = await get('/api/v1/suprimentos'); set('suprimento_id', (j.data[0] || {}).id); },
  async () => { const j = await get('/api/v1/admin/usuarios'); set('usuario_id', (j.data[0] || {}).id); },
  async () => {
    const q = '?profissional=' + insomnia.baseEnvironment.get('profissional_id') + '&data=' + insomnia.baseEnvironment.get('data_agenda') + '&unidade=' + insomnia.baseEnvironment.get('unidade_id');
    const j = await get('/api/v1/agendas/disponibilidade' + q); set('slot_inicio', (j.data[0] || {}).inicio);
  },
];
for (const p of passos) { try { await p(); } catch (e) { console.log('passo falhou:', e); } }
console.log('ids de apoio:', ['unidade_id','paciente_id','profissional_id','leito_id','suprimento_id','usuario_id','slot_inicio'].map(k => k + '=' + insomnia.baseEnvironment.get(k)).join(' | '));
